recipes.command:
mkdir -p apps/ws_server && cd apps/ws_server && npm init -y && npm install ws && cat << 'WSEOF' > server.js
import { WebSocketServer } from 'ws';
const wss = new WebSocketServer({ port: 8081 });
wss.on('connection', (ws) => {
  console.log('Cliente conectado ao WebSocket da VERY SYSTEMS');
  ws.send('Conectado à central VERY SYSTEMS');
  ws.on('message', (msg) => console.log(`Mensagem recebida: ${msg}`));
});
console.log('Servidor WebSocket ativo na porta 8081');
WSEOF
node server.js
